import os
import torch


class Config:
    # =========================================================================
    # File Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_16"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    SUBMISSION_DIR = "./submission"

    # Metadata files generated by the analysis script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Submission output
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Model checkpoint path
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Ensure necessary directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # =========================================================================
    # Reproducibility
    # =========================================================================
    SEED = 42

    # =========================================================================
    # Data Processing Parameters
    # =========================================================================
    # 1Hz Temporal Quantization
    TIME_ROUNDING = "1s"

    # Input Features (Geometric-Aware Feature Set)
    # These features will be engineered from raw GNSS logs
    FEATURE_COLS = [
        # 1. Signal Strength Statistics
        "Cn0DbHz_mean",
        "Cn0DbHz_std",
        "Cn0DbHz_min",
        "Cn0DbHz_max",
        # 2. Satellite Elevation Statistics
        "SvElevationDegrees_mean",
        "SvElevationDegrees_std",
        "SvElevationDegrees_min",
        "SvElevationDegrees_max",
        # 3. Geometric Moments (Signal-Weighted Centroid of Constellation)
        "WeightedCentroid_X",
        "WeightedCentroid_Y",
        "WeightedCentroid_Z",
        # 4. Reliability Metadata
        "SatCount",
        "RawPseudorangeUncertaintyMeters_mean",
    ]

    # Target Columns: Residuals relative to WLS baseline in Meters
    TARGET_COLS = ["dNorth_meters", "dEast_meters"]

    # Columns required from raw data to compute features/targets but not used as input
    RAW_COLS = [
        "Cn0DbHz",
        "SvElevationDegrees",
        "SvAzimuthDegrees",
        "RawPseudorangeUncertaintyMeters",
        "utcTimeMillis",
    ]

    # Baseline columns for reconstruction
    BASELINE_COLS = [
        "WlsPositionXEcefMeters",
        "WlsPositionYEcefMeters",
        "WlsPositionZEcefMeters",
    ]

    # Sequence Length for Training
    # We pad/truncate sequences to this length.
    # Most drives are under 1 hour (3600 seconds).
    MAX_SEQUENCE_LENGTH = 4096

    # =========================================================================
    # Model Architecture (1D ResUNet with ASPP)
    # =========================================================================
    IN_CHANNELS = len(FEATURE_COLS)
    OUT_CHANNELS = 2  # North, East offsets

    # Encoder settings
    ENCODER_DEPTH = 5
    START_FILTERS = 32

    # ASPP (Atrous Spatial Pyramid Pooling) settings for bottleneck
    ASPP_DILATIONS = [1, 6, 12, 18]

    # Deep Supervision
    # Weights for auxiliary losses at different decoder scales
    # Format: {decoder_layer_index: weight}
    DEEP_SUPERVISION_WEIGHTS = {
        0: 1.0,  # Final output
        1: 0.5,  # 1/2 resolution
        2: 0.25,  # 1/4 resolution
    }

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    BATCH_SIZE = 16
    EPOCHS = 30
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4

    # Optimization
    GRAD_CLIP_MAX_NORM = 1.0
    PATIENCE = 8  # Early stopping patience

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS
    ETA_MIN = 1e-6

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # =========================================================================
    # Debugging
    # =========================================================================
    # Set to True to run on a small subset of data for quick pipeline verification
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 100  # Number of samples if DEBUG is True
